// ===== CONTROL PANEL =====
const CONFIG = { dryRun: true, allowList: [], maxPerCycle: 1, replyDelayMin: 3, businessDays: [0,1,2,3,4,5,6], hours: { start: 0, end: 24 } };  // DRY RUN until MadeEA flips it live
// =========================
const BOTS = ["ai chat","chat ai","chat al"];
const EXCLUDE_CONTACT_IDS = [];   // TODO: add Prince + the MadeEA team contact ids so the setter never DMs insiders
const EXCLUDE_NAMES = ["madeea","prince andam"];   // TODO: confirm the team's IG display names
const WINDOW_MS = 24*60*60*1000;   // Instagram 24h messaging window: Meta blocks sends outside it
const data = $input.first().json;
const convs = data.conversations || [];
const sd = $getWorkflowStaticData('global');
sd.handled = sd.handled || {};
// Human/IG-safety gate. TIMEZONE is the #1 thing to confirm before go-live: the
// SOP lists geographic focus as an open question, and this clock decides what
// counts as an unsociable hour to DM a founder.
const localNow = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/London' }));
const dow = localNow.getDay();   // 0=Sun .. 6=Sat
const hr = localNow.getHours();
if (!CONFIG.businessDays.includes(dow)) return [];                 // day gate (currently 24/7)
if (hr < CONFIG.hours.start || hr >= CONFIG.hours.end) return [];  // outside business hours
const out = [];
for (const c of convs) {
  if (c.lastMessageDirection !== 'inbound') continue;
  if (c.lastMessageType !== 'TYPE_INSTAGRAM') continue;
  if (Date.now() - (c.lastMessageDate || 0) > WINDOW_MS) continue;   // outside IG 24h window -> unreachable
  if (Date.now() - (c.lastMessageDate || 0) < CONFIG.replyDelayMin*60*1000) continue;   // wait ~3 min before replying (human cadence)
  const name = (c.contactName || c.fullName || '').toLowerCase();
  if (BOTS.some(b => name.includes(b))) continue;
  if (EXCLUDE_CONTACT_IDS.includes(c.contactId)) continue;
  if (EXCLUDE_NAMES.some(n => name.includes(n))) continue;
  if (CONFIG.allowList.length && !CONFIG.allowList.includes(c.id)) continue;
  if (sd.handled[c.id] === c.lastMessageDate) continue;
  out.push({ json: {
    conversationId: c.id, contactId: c.contactId,
    contactName: c.contactName || c.fullName || c.id,
    lastMessageDate: c.lastMessageDate, dryRun: CONFIG.dryRun } });
}
return out.slice(0, CONFIG.maxPerCycle || out.length);

function hasPlaceholder(s) {
  const t = String(s);
  if (/\[[^\]]*\]|\{\{|\}\}|<[a-z_]+>/i.test(t)) return true;                    // [FIRST NAME], {{var}}, <company>
  if (/\b(your business name|business name here|their name|insert |name here|first name)\b/i.test(t)) return true;
  return false;
}
function oneMarker(s) {
  const RE = /([\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B00}-\u{2BFF}]\u{FE0F}?|:-?\)|:-?\(|;-?\)|:D)/gu;
  let n = 0;
  return s.replace(RE, m => (++n === 1 ? m : '')).replace(/ {2,}/g, ' ').replace(/\s+([.!?,])/g, '$1').trim();
}

function stripControl(s) {
  s = s.replace(/<(\w+:[\w:]+)>[\s\S]*?<\/\1>/g, '');   // paired control blocks like <budget:token_budget>..</budget:token_budget>
  s = s.replace(/<budget:[\s\S]*$/i, '');               // any trailing budget tag (closed or not)
  s = s.replace(/<\/?\w+:[\w:.\-]*[^>]*>/g, '');         // leftover namespaced/control tags
  return s.replace(/\s*[\u2014\u2013]\s*/g, ', ').replace(/[ \t]+\n/g, '\n').replace(/\n[ \t]+/g, '\n').replace(/\n{2,}/g, '\n').replace(/[ \t]{2,}/g, ' ').trim();
}

function isIdentityLeak(s) {
  const t = String(s).toLowerCase();
  if (/\b(chatgpt|gpt-?\d|language model|virtual assistant|a\.?i\.? assistant|chat\s?bot)\b/.test(t)) return true;
  if (/\b(i'?m|i am|im|i'?m actually|as|being)\s+(an?\s+|just\s+an?\s+)?(ai|a\.i\.|artificial intelligence|bot|chatbot|automated|robot|language model|ai assistant)\b/.test(t)) return true;
  if (/\b(not\s+(a\s+)?(real\s+)?(human|person)|i'?m\s+automated|i\s+am\s+automated|powered\s+by\s+ai|an\s+ai\s+(helping|assistant)|i'?m\s+a\s+bot|i\s+am\s+a\s+bot)\b/.test(t)) return true;
  return false;
}

// SOP non-negotiable #5: MadeEA is not the VA category, and one wrong noun
// undoes the whole positioning. This is the guard that has no equivalent in a
// generic setter, and it is the one most worth keeping.
function isBannedCategory(s) {
  const t = String(s).toLowerCase();
  if (/\bv\.?a\.?s?\b/.test(t) && !/\bvalue\b/.test(t)) return true;   // "VA", "VAs", "V.A."
  if (/\bvirtual assistants?\b/.test(t)) return true;
  if (/\b(outsourc|offshor)(e|ed|ing)\b/.test(t)) return true;
  return false;
}

// SOP non-negotiable #7 (never invent a claim), enforced on the one class of
// claim a regex can actually catch: money. Only the two Fact Pack figures may
// appear. Anything else \u2014 an invented rate, a discount, a made-up range \u2014 is held
// for a human rather than sent.
function isUnapprovedPrice(s) {
  const t = String(s);
  const APPROVED = /^(3,?000|3k|2,?250)$/i;
  const nums = t.match(/(?:\$|usd\s*|\u00a3|\u20ac)\s?([\d,]+(?:\.\d+)?k?)/gi) || [];
  for (const n of nums) {
    const bare = n.replace(/[^\d,.k]/gi, '');
    if (!APPROVED.test(bare)) return true;
  }
  // A percentage discount is never approved, whatever the number.
  if (/\b\d{1,2}\s?%\s?(off|discount)\b/i.test(t)) return true;
  return false;
}

function isFalsePromise(s) {
  const t = String(s).toLowerCase();
  if (/\bsent it over\b/.test(t)) return true;
  if (/\b(just )?sent (you )?(it|that|those|them|everything|the info|the details)\b/.test(t)) return true;
  if (/\b(i|we) (just )?(emailed|e-mailed|mailed)\b/.test(t)) return true;
  if (/\b(emailed|e-mailed|mailed) (it|you|that|everything|the info|those|them)\b/.test(t)) return true;
  if (/\b(i'?ll|i will|i can|i could|let me|happy to|i'?d be happy to|i'?m going to|i can go ahead and|i'?ll go ahead and)\s+(email|e-mail|send (it|you|that|everything|the info|over)|shoot you|forward (it|you|that))\b/.test(t)) return true;
  if (/\bsend (it|that|everything|the info|the details)\s+(your way|to your|over to your|to you)\b/.test(t)) return true;
  return false;
}

// SOP non-negotiable #4: max 2 sentences per DM unless quoting pricing tiers.
function isTooLong(s, quotingPrice) {
  if (quotingPrice) return false;
  const sentences = String(s).split(/(?<=[.!?])\s+/).filter(x => x.trim().length > 1);
  return sentences.length > 2;
}

function splitBubbles(s) {
  let parts = String(s).split(/\n+/).map(x => x.trim()).filter(Boolean);
  if (parts.length > 2) parts = [parts[0], parts.slice(1).join(' ')];   // SOP: keep it DM-length
  return parts;
}

const reqs = $('Build LLM Request').all();
const ors = $input.all();   // Anthropic responses, 1:1 with reqs
const out = [];
for (let i = 0; i < ors.length; i++) {
  const ctx = reqs[i].json;
  const r = ors[i].json;
  let draft = (Array.isArray(r.content) ? r.content.filter(b => b && b.type === 'text').map(b => b.text).join('') : '').trim();
  const skip = /^<SKIP/i.test(draft);            // non-prospect
  const decid = /^<HOLD/i.test(draft);           // personal decision (talk to partner / needs time)
  const handoff = /^<HANDOFF/i.test(draft);      // off-limits topic (custom scope, legal, existing client) -> human
  const notready = /^<NOTREADY/i.test(draft);    // not ready / saving for later -> go silent
  if (skip || decid || handoff || notready) draft = '';
  else draft = oneMarker(stripControl(draft));
  const clean = !skip && !decid && !handoff && !!draft;
  const leak = clean && isIdentityLeak(draft);                      // never reveal or claim an AI identity
  const category = clean && !leak && isBannedCategory(draft);       // never say VA / outsourcing / offshore
  const badprice = clean && !leak && !category && isUnapprovedPrice(draft);   // only $3,000 and $2,250 exist
  const promise = clean && !leak && !category && !badprice && !/madeea-contact/i.test(draft) && isFalsePromise(draft);
  const blank = clean && !leak && !category && !badprice && !promise && hasPlaceholder(draft);  // never ship a [FIRST NAME]
  const quotingPrice = /\$\s?(3,?000|2,?250)/i.test(draft);
  const toolong = clean && !leak && !category && !badprice && !promise && !blank && isTooLong(draft, quotingPrice);
  const nolink = ctx.noContext && clean && !leak && !category && !badprice && !promise && !blank && !toolong && /madeea-contact/i.test(draft);  // never cold-send the booking link into a no-context thread
  if (leak || category || badprice || promise || blank || toolong || nolink) draft = '';
  const hold = ctx.dryRun || skip || decid || handoff || notready || leak || category || badprice || promise || blank || toolong || nolink || !draft;
  // ===== MADEEA TAGGING =====
  // Setter lifecycle lives in its own madeea-setter-* namespace so it can never
  // trip an existing GHL automation. Lead intelligence uses the SOP's own
  // vocabulary: the three walls from Phase 4.
  const said = String(ctx.allInbound || ctx.lastInbound || '');
  const tags = [];

  // -- setter lifecycle (namespaced)
  if (skip)            tags.push('madeea-setter-not-a-fit');
  else if (decid)      tags.push('madeea-setter-deciding');
  else if (notready)   tags.push('madeea-setter-not-ready');
  else if (handoff || leak || category || badprice || promise || blank || toolong || nolink) tags.push('madeea-setter-needs-human');
  else                 tags.push('madeea-setter-engaged');

  // -- lead intelligence
  if (skip) tags.push('not good fit');
  if (decid || notready) tags.push('follow up');
  if (!skip && !decid && !notready && /madeea-contact/i.test(draft)) tags.push('ready_to_book');
  if (!skip && /\b(how much|pricing|price|cost|costs|charge|rate|rates|quote|budget|retainer|afford|expensive|investment)\b/i.test(said)) tags.push('madeea-setter-pricing-asked');

  // -- Phase 4 wall classification -> the SOP's three walls.
  // Conservative on purpose: only fires on explicit language, and only once a
  // real conversation exists (not on a one-line opener). The wall decides which
  // Phase 5 bridge is correct, so it is the single most useful tag on the lead.
  if (!skip && said.length > 40) {
    if (/\b(no time|not enough (hours|time)|swamped|slammed|drowning|buried|stretched|no bandwidth|too much on|spread thin|24\/7|always on|never stop|back to back)\b/i.test(said))
      tags.push('madeea-wall-capacity');
    if (/\b(trust|hand (it|that|things) over|let go|control|my inbox|my calendar|my accounts|confidential|nda|privacy|sensitive)\b/i.test(said))
      tags.push('madeea-wall-trust');
    if (/\b(tried (a|an|one|it|that)|didn'?t (work|stick|last)|been burned|burnt|bad experience|last one|previous (assistant|ea|hire)|had to let (them|him|her) go)\b/i.test(said))
      tags.push('madeea-wall-burned-before');
    // Not a wall, but the cleanest buying signal in the whole SOP: they already
    // have support, so the pitch shifts from hours to judgment (SOP \u00a78 stage 3).
    if (/\b(already have|i have an?) (an? )?(ea|assistant|chief of staff|pa)\b/i.test(said))
      tags.push('madeea-has-assistant');
  }
  const tag = tags[0];
  const bubbles = draft ? splitBubbles(draft) : [];
  out.push({ json: {
    conversationId: ctx.conversationId, contactId: ctx.contactId, contactName: ctx.contactName,
    lastMessageDate: ctx.lastMessageDate, lastInbound: ctx.lastInbound,
    dryRun: ctx.dryRun, skip, decid, handoff, notready, leak, category, badprice, promise, toolong, hold, tag, tags, draft, bubbles } });
}
return out;

// no-send branch: live skips/decisions get marked handled + forwarded for tagging; dry-run items stop here.
const sd = $getWorkflowStaticData('global'); sd.handled = sd.handled || {};
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j.dryRun && j.tag) {
    sd.handled[j.conversationId] = j.lastMessageDate;
    out.push({ json: j });
  }
}
return out;

const TOKEN = "REPLACE_WITH_MADEEA_GHL_PRIVATE_INTEGRATION_TOKEN";   // GHL private integration token. Replace before go-live and keep it out of version control.
const AUTH = TOKEN.toLowerCase().startsWith('bearer') ? TOKEN : ('Bearer ' + TOKEN);
const BASE = 'https://services.leadconnectorhq.com';
const H = { Authorization: AUTH, Version: '2021-07-28', Accept: 'application/json', 'Content-Type': 'application/json' };
const items = $input.all();
const out = [];
for (const it of items) {
  const c = it.json;
  let bubbles = (Array.isArray(c.bubbles) && c.bubbles.length) ? c.bubbles : [c.draft];
  bubbles = bubbles.map(b => String(b || '').trim()).filter(Boolean).slice(0, 2);   // SOP: max 2 sentences, so never more than 2 bubbles
  for (let i = 0; i < bubbles.length; i++) {
    try {
      await this.helpers.httpRequest({ method: 'POST', url: BASE + '/conversations/messages',
        headers: H, body: { type: 'IG', contactId: c.contactId, message: bubbles[i] }, json: true });
    } catch (e) {}
    if (i < bubbles.length - 1) await new Promise(r => setTimeout(r, 4000));
  }
  out.push({ json: c });
}
return out;

// mark ONLY actually-sent items as handled (1:1 with Confirm Unanswered) + carry contactId for tagging
const sent = $('Confirm Unanswered').all();
const resp = $input.all();
const sd = $getWorkflowStaticData('global'); sd.handled = sd.handled || {};
const out = [];
for (let i = 0; i < resp.length; i++) {
  const c = sent[i] ? sent[i].json : null;
  if (!c) continue;
  sd.handled[c.conversationId] = c.lastMessageDate;
  out.push({ json: { sent: true, conversationId: c.conversationId, contactId: c.contactId, contactName: c.contactName, tags: c.tags || ['madeea-setter-engaged'] } });
}
return out;

// Pre-send safety: only send if the lead's message is STILL the last one (no one replied since).
const recheck = $input.all();
const sent = $('Extract Draft').all().filter(it => !it.json.hold);   // send-branch items, 1:1 with recheck
const out = [];
for (let i = 0; i < recheck.length; i++) {
  const conv = recheck[i].json.conversation || recheck[i].json;
  const ctx = sent[i] ? sent[i].json : null;
  if (!ctx) continue;
  const lmd = conv.lastMessageDate;
  const curMs = (lmd && typeof lmd === 'object')
    ? (lmd.seconds * 1000 + Math.floor((lmd.nanoseconds || 0) / 1e6))
    : Number(lmd);
  const repliedSince = conv.lastMessageDirection && conv.lastMessageDirection !== 'inbound';   // a human on the MadeEA team replied
  const newerMsg = curMs && ctx.lastMessageDate && curMs > Number(ctx.lastMessageDate) + 2000; // a newer message arrived
  if (repliedSince || newerMsg) continue;   // already dealt with -> do NOT send
  out.push({ json: ctx });
}
return out;
